// Generates src/generated/kconfig_catalogue.ts from the built-in KDE
// settings catalogue the server embeds (server/assets). Run with
// `npm run gen:kconfig-catalogue` or `make kconfig-catalogue`; the output
// is committed like the other generated files.

import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const source = resolve(here, "../../../assets/kconfig_builtin_catalogue.json");
const target = resolve(here, "../src/generated/kconfig_catalogue.ts");

const entries = JSON.parse(readFileSync(source, "utf8"));
if (!Array.isArray(entries)) throw new Error(`${source}: expected a JSON array`);

const ids = new Set();
for (const e of entries) {
  for (const field of ["id", "file", "key", "type", "label", "category"]) {
    if (typeof e[field] !== "string" || e[field] === "") throw new Error(`entry ${JSON.stringify(e.id)}: missing ${field}`);
  }
  if (!Array.isArray(e.groupPath) || e.groupPath.length === 0) throw new Error(`entry ${e.id}: groupPath must be a non-empty array`);
  if (ids.has(e.id)) throw new Error(`duplicate catalogue id ${e.id}`);
  ids.add(e.id);
}

const header = [
  "// Code generated by scripts/gen-kconfig-catalogue.mjs from server/assets/kconfig_builtin_catalogue.json. DO NOT EDIT.",
  "/* eslint-disable */",
  "",
  'import type { KConfigCatalogueEntry } from "../views/Policies/editors/kconfigCatalogue";',
  "",
  `export const KCONFIG_BUILTIN_CATALOGUE: readonly KConfigCatalogueEntry[] = ${JSON.stringify(entries, null, 2)};`,
  "",
].join("\n");

mkdirSync(dirname(target), { recursive: true });
writeFileSync(target, header);
console.log(`wrote ${target} (${entries.length} entries)`);
